def skill():
    x, a = symbols('x a')
    h = 3*x**2 - 6*x + a
    a0 = solve(h.subs(x, 2) - 7, a)[0]
    h = h.subs(a, a0)
    even = 3*x**2 + a0
    return 2*integrate(even, (x, 0, 2))

def standard():
    t, x, a = symbols('t x a')
    S = t**3 - 3*t**2 + a*t       # S'(t) = 3t^2 - 6t + a, S(0) = 0
    h = diff(S, t).subs(t, x)
    a0 = solve(h.subs(x, 2) - 7, a)[0]
    return integrate(h.subs(a, a0), (x, -2, 2))

def unique():
    return [standard()]
